package com.harvestflow.registration.service;
import com.harvestflow.api.domain.entity.User; import com.harvestflow.api.repository.UserRepository; import com.harvestflow.registration.dto.request.*; import com.harvestflow.registration.entity.*; import com.harvestflow.registration.exception.*; import com.harvestflow.registration.repository.*; import com.harvestflow.registration.service.impl.RegistrationServiceImpl; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.Instant; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class RegistrationServiceImplTest { @Mock RegistrationSessionRepository sessions; @Mock RegistrationDocumentRepository docs; @Mock UserRepository users; @Mock PasswordEncoder encoder; @Mock OtpService otp; @Mock AadhaarVerificationService aadhaar; @Mock DocumentStorageService storage; RegistrationServiceImpl service; @BeforeEach void set(){MockitoAnnotations.openMocks(this);service=new RegistrationServiceImpl(sessions,docs,users,encoder,otp,aadhaar,storage);when(encoder.encode(any())).thenReturn("hash");}
 @Test void rejectsInternalRole(){RegistrationSession s=session();when(sessions.findByRegistrationToken("t")).thenReturn(Optional.of(s));s.setStatus(RegistrationStatus.AADHAAR_VERIFIED);assertThrows(InvalidOrInternalRoleException.class,()->service.selectRole(new RoleSelectionRequest("t","PLANNING")));}
 @Test void finalSubmitRequiresAllDocuments(){RegistrationSession s=session();s.setMobileVerified(true);s.setAadhaarVerified(true);s.setSelectedRole(SelfRegisterableRole.FARMER);s.setAddress(new RegistrationAddress());s.setStatus(RegistrationStatus.ADDRESS_COMPLETED);when(sessions.findByRegistrationToken("t")).thenReturn(Optional.of(s));when(docs.findDocumentTypesBySessionId(s.getId())).thenReturn(EnumSet.of(DocumentType.PHOTO,DocumentType.SIGNATURE));assertThrows(DocumentValidationException.class,()->service.submit(new SubmitRegistrationRequest("t")));verify(users,never()).save(any(User.class));}
 private RegistrationSession session(){RegistrationSession s=new RegistrationSession();s.setId(UUID.randomUUID());s.setRegistrationToken("t");s.setUsername("farmer1");s.setPasswordHash("hash");s.setFullName("Farmer One");s.setEmail("farmer@example.com");s.setExpiresAt(Instant.now().plusSeconds(300));return s;}}
